{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_Shopsy_margin_fact_items as SELECT SHP.* ,COALESCE(GTA_CHARGES,0) AS TOTAL_GTA ,ROUND(COALESCE(BILL_VALUE_POST_DISCOUNT - TOTAL_GTA,0),2) AS BILL_VALUE_AFTER_GTA ,CASE WHEN BILL_VALUE_AFTER_GTA < 2625 THEN 5 ELSE 18 END AS \"GST2_%\" ,ROUND((BILL_VALUE_AFTER_GTA * 100) / (100 +\"GST2_%\"),2) SALE_VALUE_AFTER_GTA ,0 AS \"REBATE_%\" ,ROUND(\"REBATE_%\" * COALESCE(BILL_VALUE_AFTER_GTA,0),2) AS REBATE_AMOUNT ,COALESCE(SALE_VALUE_AFTER_GTA + REBATE_AMOUNT ,0) AS SALE_VALUE_REBATE ,ROUND(COALESCE((SALE_VALUE_REBATE - COST),0),2) AS GROSS_MARGIN ,COALESCE(ROUND(GROSS_MARGIN / NULLIF(SALE_VALUE_REBATE, 0), 2),0) AS \"GROSS_MARGIN%\" ,0 AS COMMISSION ,ROUND(BILL_VALUE_AFTER_GTA * (COMMISSION/100),2) AS COMMISSION_VALUE ,ROUND( (( COALESCE(REV.LOCAL,0) * ZS.LOCAL/100 + COALESCE(REV.ZONAL,0) * ZS.ZONAL/100 + COALESCE(REV.NATIONAL,0) * ZS.NATIONAL/100) * COALESCE(\"CUSTOMER_RET%\",0) / 100) / NULLIF((100 - COALESCE(\"COURIER_RET%\",0) - COALESCE(\"CUSTOMER_RET%\",0)) / 100,0),2) AS REV_FRT ,COALESCE(FEE_CHARGES,0) FEE_CHARGES ,COALESCE(ROUND((FEE_CHARGES * ((100 - \"COURIER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)),2),0) AS TOTAL_FIXED_FEE ,ROUND(5 / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100),2) PACKING ,ROUND(SALE_VALUE_AFTER_GTA *(3/100),2) ADVT ,ROUND(SALE_VALUE_REBATE *(7.5/100),2) COMMON ,ROUND((COALESCE(COMMISSION_VALUE,0) + COALESCE(REV_FRT,0) + COALESCE(TOTAL_FIXED_FEE,0) + COALESCE(PACKING,0) + COALESCE(ADVT,0) + COALESCE(COMMON,0)),2) AS TOTAL_EXPENSES ,COALESCE(ROUND((TOTAL_EXPENSES/NULLIF(SALE_VALUE_REBATE,0)*100),2),0) AS \"EXPENSES_%\" ,COALESCE((GROSS_MARGIN - TOTAL_EXPENSES + REBATE_AMOUNT),0) AS NET_MARGIN ,COALESCE(ROUND((NET_MARGIN/NULLIF(SALE_VALUE_REBATE,0)*100),2),0) \"NET_MARGIN%\" FROM( SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, UPPER(A.SAP_CATEGORY) SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY CATEGORY, AVAILABLE_QUANTITY, COALESCE(REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\'),A.ARTICLES) ARTICLE, A.LENGTH AS LENGTH_CM, A.HEIGHT AS HEIGHT_CM, A.WIDTH AS WIDTH_CM, A.WEIGHT, ROUND(COALESCE(TRY_TO_DOUBLE(A.WEIGHT),0) / 1000.0,2) AS WEIGHT_KG, ROUND(( COALESCE(TRY_TO_DOUBLE(A.LENGTH),0) * COALESCE(TRY_TO_DOUBLE(A.HEIGHT),0) * COALESCE(TRY_TO_DOUBLE(A.WIDTH),0)) / 5000.0,2) AS VOLUME_WEIGHT, CASE WHEN VOLUME_WEIGHT > WEIGHT_KG THEN VOLUME_WEIGHT ELSE WEIGHT_KG END AS CHARGEABLE_WEIGHT, CASE WHEN CHARGEABLE_WEIGHT <= 0.5 THEN 0.5 WHEN CHARGEABLE_WEIGHT <= 1 THEN 1 WHEN CHARGEABLE_WEIGHT <= 1.5 THEN 1.5 WHEN CHARGEABLE_WEIGHT <= 2 THEN 2 WHEN CHARGEABLE_WEIGHT <= 2.5 THEN 2.5 WHEN CHARGEABLE_WEIGHT <= 3 THEN 3 ELSE 0 END AS WEIGHT_SLAB_HELPER, 70.0 AS \"DISCOUNT_%\", CASE WHEN \"Courier Return %\" IS NULL OR \"Courier Return %\" = 0 THEN 25 ELSE ROUND(\"Courier Return %\", 1) END AS \"COURIER_RET%\", CASE WHEN \"Customer Return %\" IS NULL OR \"Customer Return %\" = 0 THEN 11 ELSE ROUND(\"Customer Return %\", 1)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, ROUND(COALESCE(MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, ROUND(COALESCE(MRP,0) - (COALESCE(MRP,0) * \"DISCOUNT_%\" / 100),2) AS BILL_VALUE, 0 AS ADDITIONAL_DISCOUNT, ROUND(COALESCE(BILL_VALUE - ADDITIONAL_DISCOUNT,0),2) AS BILL_VALUE_POST_DISCOUNT, CASE WHEN BILL_VALUE_POST_DISCOUNT < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE_POST_DISCOUNT * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( SELECT TYPE ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" from MAPLEMONK.REDTAPE_SHOPSY_MARGIN_RETURN__ where UPPER(GENDER) != \'ALL\') CR ON UPPER(REPLACE(TRIM(A.TYPE), \' \', \'\')) = UPPER(REPLACE(TRIM(CR.TYPE), \' \', \'\')) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(CR.GENDER)) ) SHP LEFT JOIN( SELECT CATEGORY ,LOWER_PRICE ,TRY_TO_NUMBER(REPLACE(UPPER_PRICE, \',\', \'\')) UPPER_PRICE ,GTA_CHARGES ,LOWER_WEIGHT ,UPPER_WEIGHT FROM MAPLEMONK.REDTAPE_SHOPSY_MARGIN_GTA ) GTA ON LOWER(TRIM(SHP.CATEGORY)) = LOWER(TRIM(GTA.CATEGORY)) AND SHP.BILL_VALUE_POST_DISCOUNT BETWEEN GTA.LOWER_PRICE AND GTA.UPPER_PRICE AND SHP.CHARGEABLE_WEIGHT BETWEEN GTA.LOWER_WEIGHT AND GTA.UPPER_WEIGHT LEFT JOIN( SELECT CATEGORY ,LOWER_PRICE ,UPPER_PRICE ,FEE_CHARGES FROM MAPLEMONK.REDTAPE_SHOPSY_MARGIN_FIXED_FEE ) FF ON LOWER(TRIM(SHP.CATEGORY)) = LOWER(TRIM(FF.CATEGORY)) AND SHP.BILL_VALUE BETWEEN FF.LOWER_PRICE AND FF.UPPER_PRICE LEFT JOIN ( SELECT CATEGORY,LOCAL,ZONAL,NATIONAL FROM MAPLEMONK.REDTAPE_SHOPSY_MARGIN_REVERSE_FREIGHT ) REV ON LOWER(TRIM(SHP.CATEGORY))= LOWER(TRIM(REV.CATEGORY)) LEFT JOIN ( SELECT DETAILS ,CAST(REPLACE(LOCAL,\'%\',\'\') AS FLOAT) LOCAL ,CAST(REPLACE(ZONAL,\'%\',\'\') AS FLOAT) ZONAL ,CAST(REPLACE(NATIONAL,\'%\',\'\') AS FLOAT) NATIONAL FROM MAPLEMONK.REDTAPE_SHOPSY_MARGIN_ZONES_SHARE__) ZS ON 1=1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            